const INS_TACTICS=['Reconnaissance','ResourceDevelopment','InitialAccess','Execution','Persistence','PrivilegeEscalation','DefenseEvasion','CredentialAccess','Discovery','LateralMovement','Collection','CommandAndControl','Exfiltration','Impact'];

const INS_API_NAMES={azuresentinel:'Microsoft Sentinel',microsoftsentinel:'Microsoft Sentinel',teams:'Microsoft Teams',office365:'Outlook / Office 365',outlook:'Outlook',servicenow:'ServiceNow',jira:'Jira',slack:'Slack',azuread:'Entra ID',keyvault:'Key Vault',azureloganalyticsdatacollector:'Log Analytics Data Collector',azuremonitorlogs:'Azure Monitor Logs',arm:'Azure Resource Manager',http:'HTTP',sendgrid:'SendGrid',salesforce:'Salesforce',webcontents:'Web contents',azureautomation:'Azure Automation',microsoftgraphsecurity:'Graph Security',wdatp:'Defender for Endpoint'};

const INS_WORKSPACE_HOST_RE=/(^|\.)(monitor\.azure\.com|ods\.opinsights\.azure\.(com|cn|us)|opinsights\.azure\.(com|cn|us))$/i;

function insWalk(node,cb,key='',parent=null,path='$',depth=0){
  if(node==null||depth>40) return;
  cb(key,node,parent,path);
  if(Array.isArray(node)){ node.forEach((v,i)=>insWalk(v,cb,key,node,`${path}[${i}]`,depth+1)); return; }
  if(typeof node==='object') for(const k of Object.keys(node)) insWalk(node[k],cb,k,node,`${path}.${k}`,depth+1);
}

const insShort=p=>String(p||'').replace(/^Solutions\/[^/]+\//,'');

const insNorm=s=>String(s||'').toLowerCase().replace(/\(using azure functions?\)|using azure functions?|connector/g,'').replace(/[^a-z0-9()]+/g,'');

const insUniq=a=>[...new Set((a||[]).filter(Boolean))];

const insDir=p=>String(p||'').slice(0,String(p||'').lastIndexOf('/'));

const insBase=p=>String(p||'').split('/').pop();

function insPretty(s){ return String(s||'').replace(/[_-]+/g,' ').replace(/([a-z0-9])([A-Z])/g,'$1 $2').replace(/\s+/g,' ').trim(); }

function insTemplateUrl(u){ return String(u||'').replace(/\{\{\s*([^}]+?)\s*\}\}/g,'‹$1›'); }

function insTableKey(t){ return String(t||'').replace(/^Custom-/i,'').toLowerCase(); }

function insTableName(t){ return String(t||'').replace(/^Custom-/i,''); }

function insIsDefinition(c){
  const r=c.raw||{}, p=r.properties||{};
  const hasUi=!!(p.connectorUiConfig||p.connectorUIConfig||r.connectorUiConfig);
  const legacyUi=!!(r.title&&(r.instructionSteps||r.descriptionMarkdown||r.connectivityCriterias||r.connectivityCriteria||r.dataTypes));
  return hasUi||legacyUi||/dataconnectordefinitions$/i.test(String(r.type||''));
}

function insIsPackaging(c){
  const src=String(c.path||'').replace(/^\(embedded\s+/,'');
  return /(^|\/)Package\//i.test(src)||/maintemplate\.json/i.test(src);
}

function insLogicalConnectors(art){
  let all=art.connectors||[];
  const defs=all.filter(insIsDefinition);
  if(defs.length) all=defs;
  const nonPackaging=all.filter(c=>!insIsPackaging(c));
  if(nonPackaging.length) all=nonPackaging;
  const files=all.filter(c=>!c.embedded);
  const out=[];
  all.forEach(c=>{
    if(c.embedded){
      const match=files.find(d=>insNorm(d.id)===insNorm(c.id));
      if(match){ (match.mergedEmbedded=match.mergedEmbedded||[]).push(c); return; }
    }
    out.push(c);
  });
  return out;
}

function insIndexInstances(files){
  const map=new Map();
  files.filter(f=>!/(^|\/)Package\/|maintemplate\.json$/i.test(f.path)).forEach(f=>insWalk(f.raw,(k,v)=>{
    if(!v||typeof v!=='object'||Array.isArray(v)) return;
    let name=v.properties?.connectorDefinitionName||v.connectorDefinitionName;
    if(typeof name!=='string'||!name) return;
    if(/^\[/.test(name)) name=armResolve(name,f.raw);
    if(!name||/[\[{]/.test(name)) return;
    const key=name.toLowerCase();
    const list=map.get(key)||map.set(key,[]).get(key);
    if(!list.includes(f.path)) list.push(f.path);
  }));
  return map;
}

function insPackageFiles(art,def,defs){
  const files=art.files||[];
  const embeddedSource=p=>String(p||'').match(/^\(embedded\s+(.+)\)$/)?.[1];
  const extra=(def.mergedEmbedded||[]).map(e=>embeddedSource(e.path)).filter(Boolean);
  let list;
  const emb=embeddedSource(def.path);
  if(emb) list=files.filter(f=>f.path===emb);
  else{
    const dir=insDir(def.path);
    const nested=defs.filter(d=>d!==def&&d.path&&!d.path.startsWith('(')&&d.path.startsWith(dir+'/')).map(d=>insDir(d.path)).filter(d=>d.length>dir.length);
    list=files.filter(f=>f.path.startsWith(dir+'/')&&!nested.some(n=>f.path.startsWith(n+'/')));
    const siblings=defs.filter(d=>d.path&&!d.path.startsWith('(')&&insDir(d.path)===dir);
    if(siblings.length>1){
      const stem=insBase(def.path).split(/[_\-. ]/)[0].toLowerCase();
      list=list.filter(f=>insDir(f.path)!==dir||insBase(f.path).toLowerCase().includes(stem));
    }
  }
  const have=new Set(list.map(f=>f.path));
  extra.forEach(p=>files.filter(f=>f.path===p&&!have.has(f.path)).forEach(f=>list.push(f)));
  if(emb&&!list.length) list.push({path:def.path,raw:def.raw});
  return list;
}

function insResolveExpr(s){
  s=String(s||'');
  if(!/^\[/.test(s)) return s;
  let m=s.match(/^\[format\('([^']*)'\s*,\s*parameters\('([^']+)'\)\)\]$/);
  if(m) return m[1].replace('{0}',`{{${m[2]}}}`);
  m=s.match(/^\[concat\(parameters\('([^']+)'\),\s*'([^']*)'\)\]$/);
  if(m) return `{{${m[1]}}}${m[2]}`;
  return s;
}

function insDedupeSimilar(list,key=x=>x){
  const tokens=s=>new Set(String(s).toLowerCase().match(/[a-z0-9]{3,}/g)||[]);
  const kept=[];
  (list||[]).forEach(item=>{
    const t=tokens(key(item));
    if(!t.size) return;
    const similar=kept.some(k=>{ const kt=tokens(key(k)); let hit=0; t.forEach(w=>{ if(kt.has(w)) hit++; }); return hit/Math.max(1,Math.min(t.size,kt.size))>=.6; });
    if(!similar) kept.push(item);
  });
  return kept;
}

function insConnectorFiles(art,c,logical,instanceIndex){
  const files=art.files||[];
  const defIds=insUniq([c.rawId,c.raw?.properties?.connectorUiConfig?.id,c.raw?.properties?.connectorId,c.raw?.name,c.raw?.id,c.id].map(x=>String(x||'').toLowerCase()).filter(x=>x&&!/[\[{]/.test(x)));
  const pkgFiles=insPackageFiles(art,c,logical);
  const have=new Set(pkgFiles.map(f=>f.path));
  defIds.forEach(id=>(instanceIndex.get(id)||[]).forEach(p=>{
    if(have.has(p)) return;
    const f=files.find(x=>x.path===p);
    if(f){ pkgFiles.push(f); have.add(p); }
  }));
  return pkgFiles;
}

function insScanFiles(files){
  const sig={kinds:new Map(),pollers:[],resourceTypes:new Set(),stepTypes:new Set(),dataTypes:new Set(),flags:{},hosts:new Set(),
    providers:[],customs:[],inputs:[],isPreview:false,connectorIds:new Set(),graphTable:'',titles:[],tenantPerms:null,diagSettings:false};
  const seenPoller=new Set();
  const flag=(name,file,where,snippet)=>{
    const list=sig.flags[name]||(sig.flags[name]=[]);
    if(list.length<3&&!list.some(x=>x.file===file)) list.push({file,where,snippet:String(snippet||'').slice(0,140)});
  };
  files.forEach(f=>{
    const file=insShort(f.path);
    if(/(^|\/)(host|function)\.json$/i.test(f.path)) flag('functionFile',file,'file name',insBase(f.path));
    if(/function[_ -]?app/i.test(f.path)) flag('functionName',file,'file name',insBase(f.path));
    insWalk(f.raw,(key,v,parent,path)=>{
      if(/^(workspace_?key|shared_?key|primary_?key)$/i.test(key)) flag('sharedKey',file,path,key);
      if(Array.isArray(v)){
        if(key==='dataTypes') v.forEach(d=>{ const n=d?.name||(typeof d==='string'?d:''); if(n) sig.dataTypes.add(String(n)); });
        return;
      }
      if(v&&typeof v==='object'){
        if(typeof v.kind==='string'&&(typeof v.type==='string'||v.properties)) sig.kinds.set(v.kind.toLowerCase(),{file,where:`${path}.kind`,value:v.kind});
        const cfg=v.request?.apiEndpoint?v:(v.properties?.request?.apiEndpoint?v.properties:null);
        if(cfg){
          const resolvedUrl=insResolveExpr(cfg.request.apiEndpoint);
          const rawName=insResolveExpr(v.name||parent?.name||'');
          const id=resolvedUrl.toLowerCase();
          if(!seenPoller.has(id)){
            seenPoller.add(id);
            sig.pollers.push({
              name:String(rawName).split('/').pop(),url:resolvedUrl,method:cfg.request.httpMethod||'GET',
              windowMin:cfg.request.queryWindowInMin??cfg.request.queryWindowInMinutes??null,
              qps:cfg.request.rateLimitQps??cfg.request.rateLimitQPS??null,
              auth:cfg.auth?.type||cfg.auth?.authType||'',paging:cfg.paging?.pagingType||'',
              stream:cfg.dcrConfig?.streamName||'',dataType:cfg.dataType||'',file,where:path
            });
          }
        }
        if(typeof v.type==='string'){
          if(/[./]/.test(v.type)) sig.resourceTypes.add(v.type.toLowerCase());
          else sig.stepTypes.add(v.type);
          if(v.type==='Textbox'&&v.parameters?.label) sig.inputs.push(String(v.parameters.label));
          if(v.type==='OAuthForm') sig.inputs.push('OAuth client credentials');
        }
        if(key==='permissions'){
          if(Array.isArray(v.tenant)&&v.tenant.length) sig.tenantPerms=v.tenant;
          (v.resourceProvider||[]).forEach(p=>{ if(/diagnosticsettings/i.test(String(p.provider||''))) sig.diagSettings=true; });
          (v.resourceProvider||[]).forEach(p=>sig.providers.push({name:p.providerDisplayName||p.provider,text:insCleanText(p.permissionsDisplayText),scope:p.scope}));
          (v.customs||[]).forEach(c=>sig.customs.push({name:insCleanText(c.name),text:insCleanText(c.description)}));
        }
        if(v.availability?.isPreview===true||v.isPreview===true) sig.isPreview=true;
        if(typeof v.graphQueriesTableName==='string'&&!/[{]/.test(v.graphQueriesTableName)) sig.graphTable=v.graphQueriesTableName;
        if(v.title&&typeof v.id==='string'&&!/[\[{]/.test(v.id)) sig.connectorIds.add(v.id);
        if(v.title&&typeof v.title==='string'&&(v.connectorUiConfig||v.descriptionMarkdown||v.instructionSteps||v.publisher)) sig.titles.push(v.title);
        if(typeof v.connectorId==='string') sig.connectorIds.add(v.connectorId);
        return;
      }
      if(typeof v==='string'&&v.length>3){
        if(/\/api\/logs/i.test(v)) flag('dataCollectorApi',file,path,v);
        if(/workspace[_ ]?key|shared[_ ]?key|primarykey/i.test(v)) flag('sharedKey',file,path,v);
        if(/ingestion\.monitor\.azure|logs ingestion api|dcrimmutableid|dcr[_ ]?immutable|data ?collection ?endpoint/i.test(v)) flag('logsIngestion',file,path,v);
        if(/azure functions?|function ?app/i.test(v)) flag('functionText',file,path,v);
        if(/\bcef\b|common event format/i.test(v)) flag('cef',file,path,v);
        if(/\bsyslog\b/i.test(v)) flag('syslog',file,path,v);
        if(/azure monitor agent|\bAMA\b/.test(v)) flag('ama',file,path,v);
        (v.match(/https?:\/\/[^\s"'<>)\]]+/g)||[]).forEach(u=>{
          try{ const h=new URL(u.replace(/[{}]/g,'')).host.toLowerCase(); if(h&&!INS_DOC_HOST_RE.test(h)) sig.hosts.add(h); }catch{}
        });
      }
    });
  });
  return sig;
}

function insDetectMethods(sig){
  const found=[];
  const add=(key,strength,why,evidence)=>found.push({key,strength,why,evidence:(evidence||[]).slice(0,3)});
  const kind=k=>sig.kinds.get(k);
  const flagEv=n=>sig.flags[n]||[];
  const pushKind=kind('push');
  if(pushKind||sig.stepTypes.has('DeployPushConnectorButton'))
    add('ccf-push','strong',pushKind?'Data connector resource has kind "Push"':'Connector UI contains the Deploy Push Connector button',
      pushKind?[{file:pushKind.file,where:pushKind.where,snippet:'kind: Push'}]:[]);
  const pollKind=kind('restapipoller')||kind('apipolling');
  if(pollKind||sig.pollers.length)
    add('ccf-pull','strong',pollKind?`Data connector resource has kind "${pollKind.value}"`:'Polling configuration with an API endpoint request is defined',
      (pollKind?[{file:pollKind.file,where:pollKind.where,snippet:`kind: ${pollKind.value}`}]:[])
        .concat(sig.pollers.slice(0,2).map(p=>({file:p.file,where:p.where,snippet:`request.apiEndpoint: ${p.url}`}))));
  Object.keys(INS_CLOUD_KINDS).forEach(k=>{
    const hit=kind(k);
    if(hit&&!INS_NATIVE_KINDS.has(k)) add('ccf-cloud','strong',`Data connector kind "${hit.value}" (${INS_CLOUD_KINDS[k]})`,[{file:hit.file,where:hit.where,snippet:`kind: ${hit.value}`}]);
  });
  const fnEv=[...flagEv('functionFile'),...flagEv('functionName')];
  const fnResource=sig.resourceTypes.has('microsoft.web/sites');
  if(fnEv.length||fnResource){
    const ev=fnEv.slice();
    if(fnResource) ev.push({file:'(ARM template)',where:'resources[].type',snippet:'Microsoft.Web/sites'});
    add('function','strong',fnResource?'ARM template deploys a Function App (Microsoft.Web/sites)':'Function App packaging files (host.json / function.json / FunctionApp) found',ev);
  }else if(flagEv('functionText').length){
    add('function','medium','Connector instructions mention Azure Functions',flagEv('functionText'));
  }
  const agentTables=[...sig.dataTypes].filter(t=>INS_AGENT_TABLES.has(t.toLowerCase()));
  const agentSteps=[...sig.stepTypes].filter(t=>/^(InstallAgent|OmsSolutions|InstallAgentOnLinux|InstallAgentOnWindows)/i.test(t));
  const codelessOrFunction=found.some(f=>['ccf-pull','ccf-push','ccf-cloud','function'].includes(f.key)&&f.strength==='strong');
  if(codelessOrFunction){
    /* a CCF / Function path is confirmed: CommonSecurityLog/Syslog here is only the destination table, not an agent */
  }else if(agentTables.length||agentSteps.length)
    add('agent','strong',agentTables.length?`Data type ${agentTables.join(', ')} is collected by an agent`:`Connector UI uses agent step "${agentSteps[0]}"`,
      agentTables.length?[{file:'(connector dataTypes)',where:'dataTypes',snippet:agentTables.join(', ')}]:[]);
  else if(flagEv('cef').length||flagEv('syslog').length||flagEv('ama').length)
    add('agent','medium','Connector text refers to CEF / Syslog / Azure Monitor Agent',[...flagEv('cef'),...flagEv('syslog'),...flagEv('ama')]);
  const nativeHit=[...sig.kinds.keys()].find(k=>INS_NATIVE_KINDS.has(k));
  const nativeStep=[...sig.stepTypes].find(t=>/^(AAD|Dynamics365|Office365|OfficeATP|MicrosoftCloudAppSecurity|AzureSecurityCenter|ThreatIntelligence|MicrosoftThreatProtection|MicrosoftDefender|PremiumMicrosoftDefender|AzureActivityLog|AzureDiagnostics|Policy)/i.test(t));
  if(nativeHit) add('native','strong',`Data connector kind "${sig.kinds.get(nativeHit).value}" is a built-in Microsoft integration`,[{file:sig.kinds.get(nativeHit).file,where:sig.kinds.get(nativeHit).where,snippet:`kind: ${sig.kinds.get(nativeHit).value}`}]);
  else if(nativeStep) add('native','strong',`Connector UI uses the built-in "${nativeStep}" step`,[{file:'(connector instructions)',where:'instructionSteps[].type',snippet:nativeStep}]);
  else if(sig.tenantPerms) add('native','strong',`Needs tenant-level role (${sig.tenantPerms.join(', ')}) to connect a Microsoft service`,[{file:'(connector permissions)',where:'permissions.tenant',snippet:sig.tenantPerms.join(', ')}]);
  else if(sig.diagSettings) add('native','medium','Enabled through Azure diagnostic settings on the source resource',[{file:'(connector permissions)',where:'permissions.resourceProvider',snippet:'diagnosticSettings'}]);
  const dce=sig.resourceTypes.has('microsoft.insights/datacollectionendpoints')||sig.resourceTypes.has('microsoft.insights/datacollectionrules');
  const legacyApi=flagEv('dataCollectorApi').length>0||(flagEv('sharedKey').length>0&&found.some(f=>f.key==='function'));
  if(legacyApi&&!found.some(f=>['ccf-pull','ccf-push','ccf-cloud'].includes(f.key)&&f.strength==='strong')) add('http-collector','strong','Workspace shared key / Data Collector API (/api/logs) is referenced',[...flagEv('dataCollectorApi'),...flagEv('sharedKey')]);
  if((dce||flagEv('logsIngestion').length)&&!found.some(f=>['ccf-pull','ccf-push','ccf-cloud'].includes(f.key)))
    add('logs-ingestion','medium','Logs Ingestion API / DCE / DCR resources are part of the package',flagEv('logsIngestion'));
  const order=['ccf-push','ccf-pull','ccf-cloud','function','agent','native','logs-ingestion','http-collector'];
  const strongFirst=found.slice().sort((a,b)=>(a.strength===b.strength?0:a.strength==='strong'?-1:1)||order.indexOf(a.key)-order.indexOf(b.key));
  const strongKeys=insUniq(strongFirst.filter(f=>f.strength==='strong').map(f=>f.key));
  const keys=strongKeys.length?strongKeys:insUniq(strongFirst.map(f=>f.key));
  const primary=order.find(k=>keys.includes(k)&&k!=='http-collector')||keys[0]||'unknown';
  const fnKey=keys.includes('function');
  let functionIngestion=null;
  if(fnKey){
    const hasDcrApi=(flagEv('logsIngestion').length>0||dce)&&!legacyApi;
    functionIngestion=legacyApi?'Data Collector API (legacy, workspace shared key)':hasDcrApi?'Logs Ingestion API (DCR / DCE)':'Log Analytics ingestion (implemented in function code)';
  }
  return {primary,keys,found:strongFirst,functionIngestion};
}

function insPollerLabel(p){
  const tail=String(p.url||'').split('?')[0].split('/').filter(Boolean).pop()||'';
  return insPretty(p.name||tail||p.dataType||'Events');
}

function insAuthLabel(a){
  const k=String(a||'').toLowerCase();
  if(k==='apikey') return 'API key / token';
  if(k==='basic') return 'Basic (username + password)';
  if(k==='oauth2') return 'OAuth 2.0';
  if(k==='session') return 'Session login';
  if(k==='jwttoken') return 'JWT token';
  if(k==='push') return 'Microsoft Entra app (OAuth 2.0)';
  return a?insPretty(a):'';
}

function insBuildSource(method,c,sig,solutionName){
  const vendor=c.publisher||solutionName||'Vendor';
  const lines=[]; let title=`${vendor} service`; let note='';
  const pollers=sig.pollers;
  if(method.primary==='ccf-pull'){
    title=`${vendor} REST API`;
    pollers.forEach(p=>lines.push({label:insPollerLabel(p),value:insTemplateUrl(p.url),meta:`${String(p.method||'GET').toUpperCase()}${p.windowMin?` · every ${p.windowMin} min`:''}`}));
    if(pollers.some(p=>/^\{\{[^}]+\}\}/.test(p.url))) note='The API host is a connector parameter — the customer enters it when connecting.';
    if(!lines.length) sig.hosts.forEach(h=>lines.push({label:'Host',value:h}));
  }else if(method.primary==='ccf-push'){
    title='Your application / appliance';
    lines.push({label:'Delivery',value:'HTTPS POST to a Data Collection Endpoint (Logs Ingestion API)'});
    note='The sender authenticates with an Entra app created during deployment.';
  }else if(method.primary==='ccf-cloud'){
    const k=[...sig.kinds.keys()].find(x=>INS_CLOUD_KINDS[x]);
    title=INS_CLOUD_KINDS[k]||'Cloud storage / queue';
    lines.push({label:'Collected from',value:'A bucket/queue/container the customer owns'});
  }else if(method.primary==='function'){
    title=`${vendor} API (polled by a Function)`;
    [...sig.hosts].slice(0,4).forEach(h=>lines.push({label:'Referenced endpoint',value:h}));
    if(!lines.length) lines.push({label:'Endpoint',value:'Defined in function code / app settings'});
  }else if(method.primary==='agent'){
    const cef=sig.flags.cef?.length||[...sig.dataTypes].some(t=>/commonsecuritylog/i.test(t));
    title='Network / security appliance or OS logs';
    lines.push({label:'Transport',value:cef?'CEF over Syslog':'Syslog / agent'});
    lines.push({label:'Forwarder',value:'Linux log forwarder or host with Azure Monitor Agent'});
  }else if(method.primary==='native'){
    title='Microsoft service in your tenant';
    lines.push({label:'Connection',value:'Tenant-level connection enabled inside Sentinel'});
  }else{
    sig.hosts.forEach(h=>lines.push({label:'Referenced endpoint',value:h}));
  }
  return {title,lines,note};
}

function insPlaybookSummary(pb){
  const raw=pb.raw||{};
  let wf=null;
  insWalk(raw,(k,v)=>{ if(!wf&&v&&typeof v==='object'&&!Array.isArray(v)&&/microsoft\.logic\/workflows/i.test(String(v.type||''))) wf=v; });
  const def=wf?.properties?.definition||raw.definition||raw.properties?.definition||{};
  const triggers=def.triggers||{};
  const tKey=Object.keys(triggers)[0]||'';
  const t=triggers[tKey]||{};
  const pathHint=`${tKey} ${t.inputs?.path||''} ${JSON.stringify(t.inputs?.body||'').slice(0,200)}`.toLowerCase();
  let trigger='Manual / unknown';
  if(/incident/.test(pathHint)) trigger='Sentinel incident';
  else if(/alert/.test(pathHint)) trigger='Sentinel alert';
  else if(/entity/.test(pathHint)) trigger='Sentinel entity (manual)';
  else if(String(t.type).toLowerCase()==='request') trigger='HTTP request';
  else if(String(t.type).toLowerCase()==='recurrence') trigger='Schedule';
  const text=JSON.stringify(raw);
  const apis=insUniq([...text.matchAll(/managedApis\/([a-z0-9_]+)/gi)].map(m=>m[1].toLowerCase()).concat([...text.matchAll(/\['([a-z0-9_]+)'\]\['connectionId'\]/gi)].map(m=>m[1].toLowerCase())))
    .filter(a=>a!=='$connections').map(a=>a.replace(/[\s_-]*\d+$/,'')).map(a=>INS_API_NAMES[a]||insPretty(a));
  const apiList=insUniq(apis);
  const parts=String(pb.path||'').split('/');
  const pi=parts.findIndex(p=>/^playbooks?$/i.test(p));
  const rest=pi>=0?parts.slice(pi+1,-1):[];
  const variant=rest.length>=2&&/(trigger|incident|alert|entity|manual|logingestion)/i.test(rest[rest.length-1])?rest[rest.length-1]:'';
  const folder=pb.path&&!pb.path.startsWith('(')?(variant?rest[rest.length-2]:parts.slice(-2,-1)[0]):'';
  const base=insBase(pb.path||'').replace(/\.json$/i,'');
  const baseName=/^(azuredeploy|maintemplate)/i.test(base)?(folder||pb.id):(pb.id&&!/^(azuredeploy)/i.test(pb.id)?pb.id:base);
  const name=insPretty(baseName)+(variant?` (${insPretty(variant)})`:'');
  const allHosts=insUniq((pb.connections?.endpoints||pb.endpoints||[]).filter(h=>!INS_DOC_HOST_RE.test(h)));
  const endpoints=allHosts.filter(h=>!INS_WORKSPACE_HOST_RE.test(h));
  const writesToWorkspace=/logingestion|logs ingestion/i.test(pb.path||'')||allHosts.some(h=>INS_WORKSPACE_HOST_RE.test(h))||apiList.includes('Log Analytics Data Collector');
  return {name,trigger,connectors:apiList,endpoints,actions:Object.keys(def.actions||{}).length,
    writesToWorkspace,
    description:raw.metadata?.description||raw.metadata?.comments||def.description||'',path:pb.path};
}

function insCollectTableSchemas(files){
  const out=new Map();
  files.forEach(f=>{
    const template=f.raw;
    insWalk(f.raw,(k,v)=>{
      if(!v||typeof v!=='object'||Array.isArray(v)) return;
      if(/operationalinsights\/workspaces\/tables$/i.test(String(v.type||''))||(v.properties?.schema?.columns&&v.properties?.schema?.name)){
        const schema=v.properties?.schema||{};
        const name=schema.name||armResolve(String(v.name||''),template);
        if(name&&Array.isArray(schema.columns)) out.set(insTableKey(name),{columns:schema.columns.length,retention:v.properties?.retentionInDays,plan:v.properties?.plan||''});
      }
    });
  });
  return out;
}

function insFindManifest(files){
  return files.find(f=>f.raw&&!Array.isArray(f.raw)&&(f.raw['Data Connectors']||f.raw['Analytic Rules']||f.raw.BasePath)&&/(^|\/)Data\//i.test(f.path))?.raw||null;
}

function insCleanMarkdown(s){ return String(s||'').replace(/\[([^\]]+)\]\([^)]*\)/g,'$1').replace(/\*\*|__/g,'').replace(/\r/g,'').trim(); }

function insCleanText(s){
  const t=insCleanMarkdown(s).replace(/\[?\s*See the documentation[^.\]]*[.\]]*/gi,'').replace(/\(?https?:\/\/\S+\)?/g,'').replace(/\s+/g,' ').replace(/\s+\./g,'.').trim();
  const sentences=t.split(/(?<=[.!?])\s+/).filter(Boolean);
  let out=sentences[0]||t;
  if(sentences[1]&&out.length<60&&!/^(follow|see|refer)/i.test(sentences[1])) out+=' '+sentences[1];
  return out.replace(/\b(follow|see|refer)\b[^.]*$/i,'').replace(/\s+/g,' ').trim();
}

function insDcrName(d){
  const id=String(d.id||'');
  if(/^(dcr|datacollectionrule|azuredeploy|maintemplate)(\.json)?$/i.test(id)||/\.json$/i.test(id)){
    const folder=String(d.path||'').split('/').slice(-2,-1)[0]||'';
    return (folder?insPretty(folder).replace(/\s*ccp$/i,'')+' ':'')+'DCR';
  }
  return id;
}

function insApplyTitleHints(method,name){
  const title=String(name||'');
  const says=(re)=>re.test(title);
  const rebuild=(keys,why)=>{
    method.keys=keys; method.primary=['ccf-push','ccf-pull','ccf-cloud','function','agent','native','logs-ingestion','http-collector'].find(k=>keys.includes(k))||method.primary;
    method.found=method.found.filter(f=>keys.includes(f.key));
    method.found.unshift({key:method.primary,strength:'strong',why,evidence:[{file:'(connector title)',where:'title',snippet:title}]});
    method.found=method.found.filter((f,i,a)=>a.findIndex(x=>x.key===f.key&&x.why===f.why)===i);
    if(!keys.includes('function')) method.functionIngestion=null;
  };
  const ccf=['ccf-pull','ccf-push','ccf-cloud'];
  if(says(/\busing azure functions?\b/i)&&!method.keys.includes('function')){
    method.keys=['function'];
    method.found=[{key:'function',strength:'strong',why:'Connector title states it uses Azure Functions',evidence:[{file:'(connector title)',where:'title',snippet:title}]}];
    method.primary='function';
    method.functionIngestion='Log Analytics ingestion (implemented in function code)';
  }else if(says(/using azure functions?|azure function/i)&&method.keys.includes('function')&&method.keys.some(k=>ccf.includes(k)))
    rebuild(method.keys.filter(k=>!ccf.includes(k)),'Connector title states it uses Azure Functions');
  else if(says(/codeless|\bccf\b|\bccp\b/i)&&method.keys.some(k=>ccf.includes(k))&&method.keys.some(k=>['function','agent','http-collector'].includes(k)))
    rebuild(method.keys.filter(k=>ccf.includes(k)),'Connector title states it is a Codeless Connector Framework connector');
  return method;
}

const INS_ARCH_CATEGORIES={
  ccf:{label:'CCF',cls:'ccf'},
  logs:{label:'Logs Ingestion API',cls:'ccf'},
  function:{label:'Azure Function',cls:'http'},
  http:{label:'HTTP Data Collector API',cls:'http'},
  legacy:{label:'Legacy (CEF/AMA)',cls:'legacy'},
  native:{label:'Native',cls:'none'},
  unclassified:{label:'Unclassified',cls:'unknown'}
};

function insArchCategory(c){
  const p=c.method.primary;
  if(['ccf-pull','ccf-push','ccf-cloud'].includes(p)) return 'ccf';
  if(p==='function'){
    const via=String(c.method.functionIngestion||'');
    if(/Data Collector/i.test(via)) return 'http';
    if(/Logs Ingestion/i.test(via)) return 'logs';
    return 'function';
  }
  if(p==='logs-ingestion') return 'logs';
  if(p==='http-collector') return 'http';
  if(p==='agent') return 'legacy';
  if(p==='native') return 'native';
  return 'unclassified';
}

function insReconcileArchitecture(analysis,ins){
  if(!analysis||!ins) return analysis;
  const counts={};
  const aligned=Array.isArray(analysis.connectors)&&analysis.connectors.length===ins.connectors.length;
  ins.connectors.forEach((c,i)=>{
    const k=insArchCategory(c);
    c.archCategory=k;
    counts[k]=(counts[k]||0)+1;
    if(aligned) analysis.connectors[i].category=k;
  });
  const present=Object.keys(INS_ARCH_CATEGORIES).filter(k=>counts[k]);
  analysis.categoryCounts=counts;
  analysis.architectureSet=present;
  analysis.label=present.length?present.map(k=>INS_ARCH_CATEGORIES[k].label).join(' + '):analysis.type;
  analysis.primaryClass=present.length?INS_ARCH_CATEGORIES[present[0]].cls:null;

  /* No connector but playbooks: this is an automation pack, whatever keywords the packaging files contain. */
  const pbs=ins.content.playbooks;
  if(!ins.connectors.length&&pbs.length&&!ins.counts.analytics&&!ins.counts.hunting){
    const writing=pbs.filter(p=>p.writesToWorkspace).length;
    analysis.label=writing?'Automation-only · playbooks write to Log Analytics':'No ingestion / Automation-only';
    analysis.primaryClass='none';
    analysis.automationOnly=true;
    if(analysis.confidence<.85){ analysis.confidence=.85; analysis.lowConfidence=false; }
  }

  /* Confidence also reflects the per-connector evidence strength; it can be raised, never lowered. */
  if(ins.connectors.length){
    const perConnector=ins.connectors.map(c=>{
      if(c.archCategory==='unclassified') return .1;
      const hit=(c.method.found||[]).find(f=>f.key===c.method.primary);
      return hit?.strength==='strong'?.9:.6;
    });
    const evidenceConfidence=perConnector.reduce((s,v)=>s+v,0)/perConnector.length;
    if(evidenceConfidence>analysis.confidence){
      analysis.confidence=evidenceConfidence;
      analysis.lowConfidence=analysis.confidence<.6;
    }
  }
  const breakdown=present.map(k=>`${INS_ARCH_CATEGORIES[k].label} ×${counts[k]}`).join(', ');
  if(Array.isArray(analysis.reasoningLines)){
    const identified=present.some(k=>k!=='unclassified');
    analysis.reasoningLines=analysis.reasoningLines.filter(l=>!/^(Confidence:|⚠ Low confidence)/.test(l)&&!(identified&&/^No decisive CCF, HTTP, or Legacy anchors/.test(l)));
    analysis.reasoningLines[0]=`Final: ${analysis.label}${analysis.lowConfidence?` ⚠ low confidence (${Math.round(analysis.confidence*100)}%)`:''}`;
    analysis.reasoningLines.splice(1,0,`Confidence: ${Math.round(analysis.confidence*100)}%`);
    if(analysis.lowConfidence) analysis.reasoningLines.splice(2,0,'⚠ Low confidence — manual review recommended.');
    if(breakdown) analysis.reasoningLines.splice(analysis.lowConfidence?3:2,0,`Collection methods (${ins.connectors.length} connectors): ${breakdown}`);
    analysis.reasoning='Architecture Reasoning:\n'+analysis.reasoningLines.map(l=>'• '+l).join('\n');
  }
  return analysis;
}

function buildSolutionInsights(art,meta){
  const files=art.files||[];
  const manifest=insFindManifest(files);
  const sm=meta?.rawSolutionMeta||{};
  const solutionName=meta?.solutionName||'Solution';
  const logical=insLogicalConnectors(art);
  const instanceIndex=insIndexInstances(files);
  const allDcrs=(art.dcrs||[]).concat((art.coreFiles||[]).filter(x=>x.coreKind==='dcr'));
  const schemas=insCollectTableSchemas(files);

  const analytics=(art.analytics||[]).map(a=>({
    name:a.id,severity:a.severity||'Unknown',tactics:insUniq(String(a.tactics||'').split(/[,;]/).map(s=>s.trim())),
    techniques:[].concat(a.techniques||[]),tables:insUniq((a.references?.tables||a.tables||[]).map(insTableName)),
    frequency:a.frequency||'',period:a.period||'',kind:a.ruleKind||'',description:a.description||'',
    connectorIds:insUniq((a.requiredConnectors||[]).map(r=>String(r.connectorId||r).toLowerCase())),path:a.path,unresolved:a.references?.unresolved||[]
  }));
  const hunting=(art.hunting||[]).map(h=>({
    name:h.id,tactics:insUniq(String(h.tactics||'').split(/[,;]/).map(s=>s.trim())),techniques:[].concat(h.techniques||[]),
    tables:insUniq((h.references?.tables||h.tables||[]).map(insTableName)),description:h.description||'',
    connectorIds:insUniq((h.requiredConnectors||[]).map(r=>String(r.connectorId||r).toLowerCase())),path:h.path,unresolved:h.references?.unresolved||[]
  }));
  const workbooks=(art.workbooks||[]).map(w=>({name:insPretty(/^(azuredeploy|maintemplate)/i.test(insBase(w.path||'').replace(/\.json$/i,''))?(w.path||'').split('/').slice(-2,-1)[0]:(w.id&&w.id!==insBase(w.path||'').replace(/\.json$/i,'')?w.id:insBase(w.path||'').replace(/\.json$/i,''))),
    tables:insUniq((w.references?.tables||w.tables||[]).map(insTableName)),description:w.description||'',path:w.path,unresolved:w.references?.unresolved||[]}));
  const parsers=(art.functions||[]).map(f=>({name:f.id,alias:f.functionAlias||'',tables:insUniq((f.references?.tables||f.tables||[]).map(insTableName)),description:f.description||'',path:f.path}));
  const playbooks=(art.playbooks||[]).map(insPlaybookSummary);
  const watchlists=(art.watchlists||[]).map(w=>({name:insPretty(w.id),description:w.description||''}));
  const notebooks=(art.notebooks||[]).map(n=>({name:insPretty(n.id),cells:n.cellCount||0}));
  const automationRules=art.automationRules||[];

  const connectors=logical.map(c=>{
    const defIds=insUniq([c.rawId,c.raw?.properties?.connectorUiConfig?.id,c.raw?.properties?.connectorId,c.raw?.name,c.raw?.id,c.id].map(x=>String(x||'').toLowerCase()).filter(x=>x&&!/[\[{]/.test(x)));
    const pkgFiles=insConnectorFiles(art,c,logical,instanceIndex);
    const havePaths=new Set(pkgFiles.map(f=>f.path));
    const sig=insScanFiles(pkgFiles);
    const method=insDetectMethods(sig);
    if(method.primary==='unknown'&&/^microsoft/i.test(c.publisher||'')){
      method.primary='native'; method.keys=['native'];
      method.found=[{key:'native',strength:'medium',why:'Microsoft-published connector with no custom collection mechanism — a built-in integration',evidence:[]}];
    }
    const pkgPaths=new Set(pkgFiles.map(f=>f.path));
    const dcrs=allDcrs.filter(d=>pkgPaths.has(d.path)).map(d=>({
      id:insDcrName(d),flows:(d.flowsData||[]).length,transform:(d.flowsData||[]).some(f=>f.hasTransform),
      outputTables:insUniq((d.flowsData||[]).flatMap(f=>f.outputTables).map(insTableName)),
      inputStreams:insUniq((d.flowsData||[]).flatMap(f=>f.streams))
    }));
    const tableMap=new Map();
    const addTable=t=>{ const n=insTableName(t); if(!n||!/^[A-Za-z_][A-Za-z0-9_]*$/.test(n)) return; const k=n.toLowerCase(); if(!tableMap.has(k)||(tableMap.get(k)===k&&n!==k)) tableMap.set(k,n); };
    (c.tables||[]).forEach(addTable); sig.dataTypes.forEach(addTable); addTable(sig.graphTable);
    sig.pollers.forEach(p=>{ addTable(p.dataType); addTable(p.stream); });
    dcrs.forEach(d=>d.outputTables.forEach(addTable));
    const tables=[...tableMap.values()];
    const source=insBuildSource(method,c,sig,solutionName);
    const authSet=insUniq(sig.pollers.map(p=>insAuthLabel(p.auth)));
    if(method.primary==='ccf-push') authSet.push(insAuthLabel('push'));
    const windows=sig.pollers.map(p=>p.windowMin).filter(v=>v!=null);
    const ids=insUniq([c.rawId,c.raw?.properties?.connectorUiConfig?.id,...sig.connectorIds].map(x=>String(x||'').toLowerCase()));
    const embeddedTitle=(c.mergedEmbedded||[]).map(x=>x.id).find(t=>t&&/\(.*\)/.test(t)&&insNorm(t)===insNorm(c.id));
    const title=embeddedTitle||(sig.titles.find(t=>insNorm(t)===insNorm(c.id))||c.id);
    insApplyTitleHints(method,title);
    const functionApps=(art.functionApps||[]).filter(f=>pkgPaths.has(f.path)).map(f=>f.id);
    const requiredBy=analytics.filter(a=>a.connectorIds.some(i=>ids.includes(i))).length;
    const legacyByName=/deprecat|legacy/i.test(`${c.id} ${c.description||''}`);
    return {
      name:title,publisher:c.publisher||'',description:insCleanMarkdown(c.description||''),
      ids,definitionPath:c.path,files:[...pkgPaths].map(insShort),method,methodInfo:INS_METHODS[method.primary],
      source,auth:authSet,inputs:insUniq(sig.inputs),prerequisites:{
        permissions:insDedupeSimilar(insUniq(sig.providers.map(p=>`${p.name||'Workspace'}: ${p.text||''}`.trim()))),
        customs:insDedupeSimilar(sig.customs,x=>`${x.name} ${x.text}`)},
      schedule:{windowMin:windows.length?Math.min(...windows):null,paging:insUniq(sig.pollers.map(p=>p.paging)),qps:insUniq(sig.pollers.map(p=>p.qps).filter(v=>v!=null))},
      pollers:sig.pollers.map(p=>({label:insPollerLabel(p),url:insTemplateUrl(p.url),method:String(p.method||'GET').toUpperCase(),windowMin:p.windowMin,stream:p.stream,table:p.dataType||insTableName(p.stream)})),
      tables,dcrs,hasTransform:dcrs.some(d=>d.transform),hasDce:sig.resourceTypes.has('microsoft.insights/datacollectionendpoints')||sig.pollers.some(p=>!!p.stream)||method.primary==='ccf-push',
      functionApps,usesFunction:method.keys.includes('function'),requiredBy,isPreview:sig.isPreview,legacy:legacyByName,
      endpointsReferenced:[...sig.hosts].slice(0,8)
    };
  });

  /* Agent-based connectors often declare no tables: attribute the standard agent tables that this solution's content queries. */
  const queriedByContent=insUniq([...analytics,...hunting,...workbooks,...parsers].flatMap(x=>x.tables)).map(t=>t.toLowerCase());
  connectors.filter(c=>c.method.primary==='agent'&&!c.tables.length).forEach(c=>{
    ['CommonSecurityLog','Syslog','SecurityEvent','WindowsEvent'].forEach(t=>{ if(queriedByContent.includes(t.toLowerCase())) c.tables.push(t); });
    if(c.tables.length) c.tablesInferred=true;
  });

  /* Queries often call a parser alias (e.g. `OktaSSO | where …`): resolve such identifiers against the solution's own tables and parsers. */
  const known=new Map();
  connectors.forEach(c=>c.tables.forEach(t=>known.set(t.toLowerCase(),{kind:'table',tables:[t]})));
  parsers.forEach(p=>[p.name,p.alias].filter(Boolean).forEach(n=>{ const k=String(n).toLowerCase(); if(!known.has(k)) known.set(k,{kind:'parser',parser:p,tables:p.tables}); }));
  [...analytics,...hunting,...workbooks].forEach(item=>{
    (item.unresolved||[]).forEach(tok=>{
      const hit=known.get(String(tok).toLowerCase());
      if(!hit) return;
      const add=t=>{ if(!item.tables.some(x=>x.toLowerCase()===t.toLowerCase())) item.tables.push(t); };
      if(hit.kind==='table') add(hit.tables[0]);
      else{ item.viaParsers=insUniq([...(item.viaParsers||[]),hit.parser.name]); hit.tables.forEach(add); }
    });
  });

  const producedBy=new Map();
  connectors.forEach(c=>c.tables.forEach(t=>{ const k=t.toLowerCase(); (producedBy.get(k)||producedBy.set(k,[]).get(k)).push(c.name); }));
  const tableRows=new Map();
  const touch=(name,kind,item)=>{
    const k=name.toLowerCase();
    if(!tableRows.has(k)) tableRows.set(k,{name,producers:producedBy.get(k)||[],analytics:[],hunting:[],workbooks:[],parsers:[],schema:schemas.get(k)||null,custom:/_(CL|CE|CF)$/i.test(name)});
    if(item) tableRows.get(k)[kind].push(item);
  };
  connectors.forEach(c=>c.tables.forEach(t=>touch(t)));
  analytics.forEach(a=>a.tables.forEach(t=>touch(t,'analytics',a.name)));
  hunting.forEach(h=>h.tables.forEach(t=>touch(t,'hunting',h.name)));
  workbooks.forEach(w=>w.tables.forEach(t=>touch(t,'workbooks',w.name)));
  parsers.forEach(p=>p.tables.forEach(t=>touch(t,'parsers',p.name)));
  const tables=[...tableRows.values()].sort((a,b)=>(b.producers.length-a.producers.length)||((b.analytics.length+b.hunting.length+b.workbooks.length)-(a.analytics.length+a.hunting.length+a.workbooks.length)));

  connectors.forEach(c=>{
    const own=new Set(c.tables.map(t=>t.toLowerCase()));
    const hit=list=>list.filter(x=>x.tables.some(t=>own.has(t.toLowerCase()))||(x.connectorIds||[]).some(i=>c.ids.includes(i))).length;
    c.consumers={analytics:hit(analytics),hunting:hit(hunting),workbooks:hit(workbooks),parsers:hit(parsers)};
  });

  const severityOrder=['High','Medium','Low','Informational'];
  const severity=Object.fromEntries(severityOrder.map(s=>[s,analytics.filter(a=>a.severity.toLowerCase()===s.toLowerCase()).length]));
  const tacticCounts={};
  analytics.concat(hunting).forEach(x=>x.tactics.forEach(t=>{ const k=t.replace(/\s+/g,''); if(k) tacticCounts[k]=(tacticCounts[k]||0)+1; }));

  const description=insCleanMarkdown(manifest?.Description||'');
  const techMarker=description.search(/Underlying Microsoft Technologies/i);
  const intro=(techMarker>0?description.slice(0,techMarker):description).split(/\n\s*\n/)[0].trim();
  const rawDescription=String(manifest?.Description||'');
  const techBlock=techMarker>=0?rawDescription.slice(rawDescription.search(/Underlying Microsoft Technologies/i)):'';
  const technologies=insUniq([...techBlock.matchAll(/\[([^\]]+)\]\(/g)].map(m=>m[1].trim()).filter(t=>!/preview|supplemental/i.test(t)));
  const logoSrc=String(manifest?.Logo||'').match(/src=["']([^"']+)["']/i)?.[1]||'';

  const methodKeys=insUniq(connectors.flatMap(c=>c.method.keys.length?[c.method.primary,...c.method.keys.filter(k=>k!==c.method.primary&&c.method.primary==='unknown')]:[c.method.primary]));
  const primaryMethods=insUniq(connectors.map(c=>c.method.primary));
  const functionConnectors=connectors.filter(c=>c.usesFunction);
  const serverless=connectors.filter(c=>['ccf-pull','ccf-push','ccf-cloud','native'].includes(c.method.primary));
  let functionAnswer={state:'no',text:'No Azure Function is required.'};
  if(functionConnectors.length){
    functionAnswer=functionConnectors.length===connectors.length||!serverless.length
      ?{state:'yes',text:'Yes — data collection runs in an Azure Function App you deploy and operate.'}
      :{state:'optional',text:`Optional — ${functionConnectors.length} of ${connectors.length} connectors use an Azure Function (customer-hosted); the others are serverless.`};
  }else if(/azure functions?/i.test(technologies.join(' '))){
    functionAnswer={state:'optional',text:'The solution lists Azure Functions as a dependency.'};
  }
  const findings=[];
  const inv=STATE.inventory;
  if(inv&&(inv.failed>0||inv.truncated)) findings.push({level:'warn',text:`Partial inventory: ${inv.fetched} of ${inv.expected} listed files were analysed${inv.truncated?' and the GitHub file listing was truncated':''}. Counts and detection may be incomplete.`});
  if(functionConnectors.length&&serverless.length) findings.push({level:'info',text:`Two collection paths ship in the same solution — serverless: ${serverless.map(c=>c.name).join(', ')}; Azure Function: ${functionConnectors.map(c=>c.name).join(', ')}. Prefer the serverless connector for new deployments.`});
  connectors.filter(c=>c.method.found.some(f=>f.key==='http-collector')).forEach(c=>findings.push({level:'warn',text:`${c.name} references the legacy HTTP Data Collector API (shared key). Microsoft is moving ingestion to the Logs Ingestion API / CCF.`}));
  connectors.filter(c=>c.method.primary==='unknown').forEach(c=>findings.push({level:'warn',text:`${c.name}: the repository JSON does not reveal how data is collected — check the connector page in the Sentinel content hub.`}));
  const previews=connectors.filter(c=>c.isPreview);
  if(previews.length) findings.push({level:'info',text:`${previews.length===connectors.length&&previews.length>1?'All connectors are':previews.map(c=>c.name).slice(0,3).join(', ')+(previews.length>3?` +${previews.length-3} more`:'')+(previews.length===1?' is':' are')} marked as Preview — behaviour and billing may change.`});
  if(!connectors.length) findings.push({level:'info',text:'This solution ships no data connector. Its content analyses data that other connectors/solutions already ingest.'});
  if(!analytics.length&&!hunting.length) findings.push({level:'info',text:'No analytics rules or hunting queries were found in the repository files for this solution.'});
  const withTransform=connectors.filter(c=>c.hasTransform);
  if(withTransform.length) findings.push({level:'good',text:`${withTransform.length===connectors.length&&withTransform.length>1?'All connectors apply':withTransform.map(c=>c.name).slice(0,3).join(', ')+(withTransform.length>3?` +${withTransform.length-3} more`:'')+(withTransform.length===1?' applies':' apply')} an ingestion-time transformation in the Data Collection Rule.`});
  const customTables=tables.filter(t=>t.custom&&t.producers.length);
  if(customTables.length) findings.push({level:'info',text:`Creates ${customTables.length} custom table${customTables.length>1?'s':''} (${customTables.map(t=>t.name).join(', ')}) — ingestion into these tables is billed.`});
  const queriedOnly=tables.filter(t=>!t.producers.length);

  return {
    solution:{name:solutionName,publisher:connectors.find(c=>c.publisher)?.publisher||sm.support?.name||manifest?.Author||'',author:manifest?.Author||'',version:sm.version||manifest?.Version||'',
      support:sm.support||null,firstPublish:sm.firstPublishDate||'',lastPublish:sm.lastPublishDate||'',categories:meta?.categories||[],domains:meta?.domains||[],
      verticals:normalizeMetaList(sm.categories?.verticals),providers:normalizeMetaList(sm.providers),description:intro,technologies,logo:logoSrc,
      is1P:manifest?.Is1PConnector===true,path:manifest?'manifest':''},
    connectors,primaryMethods:primaryMethods,methodKeys,functionAnswer,
    content:{analytics,hunting,workbooks,parsers,playbooks,watchlists,notebooks,automationRules,severity,tacticCounts},
    tables,queriedOnly,findings,
    counts:{connectors:connectors.length,tables:tables.filter(t=>t.producers.length).length,analytics:analytics.length,hunting:hunting.length,workbooks:workbooks.length,playbooks:playbooks.length,parsers:parsers.length,watchlists:watchlists.length,notebooks:notebooks.length,automationRules:automationRules.length}
  };
}

export { INS_TACTICS, INS_ARCH_CATEGORIES, INS_METHODS, insReconcileArchitecture, insArchCategory, buildSolutionInsights, normalizeMetaList, insTemplateUrl, insPollerLabel, insPretty, insDedupeSimilar, insShort, insCleanMarkdown, insApplyTitleHints, insNorm, insAuthLabel, insBuildSource, INS_CLOUD_KINDS, insDcrName, insDetectMethods, insUniq, INS_AGENT_TABLES, INS_NATIVE_KINDS, insScanFiles, INS_DOC_HOST_RE, insCleanText, insResolveExpr, insWalk, insBase, insConnectorFiles, insPackageFiles, insDir, insPlaybookSummary, INS_WORKSPACE_HOST_RE, INS_API_NAMES, insTableName, insCollectTableSchemas, insTableKey, armResolve, insIndexInstances, insLogicalConnectors, insIsPackaging, insIsDefinition, insFindManifest, analyzeCreateUiDefinition, analyzeSolutionArchitecture, extractSolutionMeta, buildArtifacts, classifyArtifact, fetchSolutionFiles, listSolutionJsonPaths, detectDefaultBranch, listSolutions }
